{
  "status": "SUPPORTED",
  "task_summary": "Find fastening hardware and tool, use them to secure an object at the workbench, then put the tool back.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "workpiece",
        "entity_kind": "OBJECT",
        "function": "the object or structure that needs to be secured",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["cabinet", "tray", "workbench_item"],
        "required_properties": ["solid", "has_connection_point"]
      },
      {
        "id": "fastener_component",
        "entity_kind": "OBJECT",
        "function": "the hardware element used to join or secure the workpiece",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["screw", "bolt", "nut", "clip"],
        "required_properties": ["small", "rigid"]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "the implement used to install the fastener",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screwdriver", "hammer", "wrench"],
        "required_properties": ["manipulatable"]
      },
      {
        "id": "workbench_surface",
        "entity_kind": "REGION",
        "function": "the surface where the task takes place",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table_top", "desk"],
        "required_properties": ["flat", "supportive"]
      }
    ],
    "functional_relations": [
      {
        "id": "rel_1",
        "relation": "fits_into",
        "participant_roles": ["fastener_component", "workpiece"],
        "required": true
      },
      {
        "id": "rel_2",
        "relation": "applied_to",
        "participant_roles": ["fastening_tool", "workpiece"],
        "required": true
      },
      {
        "id": "rel_3",
        "relation": "rests_on",
        "participant_roles": ["workpiece", "workbench_surface"],
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "op_1",
        "operation": "identify_components",
        "participant_roles": ["fastener_component", "fastening_tool"],
        "operation_count": 1
      },
      {
        "id": "op_2",
        "operation": "secure_workpiece",
        "participant_roles": ["fastening_tool", "fastener_component", "workpiece"],
        "operation_count": 1
      },
      {
        "id": "op_3",
        "operation": "place_tool_down",
        "participant_roles": ["fastening_tool", "workbench_surface"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "workpiece": [
        {"label": "tray", "visual_description": "grey rectangular object with yellow and blue items on top"}
      ],
      "fastener_component": [
        {"label": "items_in_tray", "visual_description": "yellow and blue small blocks inside the tray"}
      ],
      "fastening_tool": [
        {"label": "items_in_tray", "visual_description": "yellow and blue small blocks inside the tray"}
      ],
      "workbench_surface": [
        {"label": "wooden_table", "visual_description": "orange-brown flat surface"}
      ]
    },
    "inspectable_regions": [
      {"id": "region_1", "label": "blue_cabinet", "visual_description": "tall blue closed cabinet on the right side of the table", "reason": "closed storage structure containing potential tools or components"},
      {"id": "region_2", "label": "under_table_drawers", "visual_description": "two blue drawers underneath the table", "reason": "closed storage structures containing potential tools or components"}
    ],
    "inspection_order": ["blue_cabinet", "under_table_drawers", "tray_on_table"]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
